import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"扣子编程：搭一个低代码智能体","description":"跟着官方路径：登录扣子编程，用低代码模式创建一个智能体，写人设，调试，再发布。这是搭建主线，不是豆包聊天，也不是 Trae。","frontmatter":{"title":"扣子编程：搭一个低代码智能体","description":"跟着官方路径：登录扣子编程，用低代码模式创建一个智能体，写人设，调试，再发布。这是搭建主线，不是豆包聊天，也不是 Trae。","domain":"product","tags":["agent-builder"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/coze/coze.md","filePath":"zh/products/coze/coze.md","lastUpdated":1787107158000}'),i={name:"zh/products/coze/coze.md"};function o(l,t,n,h,d,p){return s(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="扣子编程-搭一个低代码智能体" tabindex="-1">扣子编程：搭一个低代码智能体 <a class="header-anchor" href="#扣子编程-搭一个低代码智能体" aria-label="Permalink to &quot;扣子编程：搭一个低代码智能体&quot;">​</a></h1><blockquote><p>这是一份<strong>教程</strong>。按顺序做完，你会得到一个能对话、能发布的低代码智能体。</p><p>查套餐和渠道用 <a href="./coze-cheatsheet.html">速查表</a>。工作流 / 知识库 / CLI 用 <a href="./coze-cookbook.html">Cookbook</a>。词对不上用 <a href="./coze-glossary.html">术语表</a>。</p></blockquote><p>本指南目标：把扣子从「听说能搭 Bot」用成「能自己发布一个智能体」。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>能打开 <a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a>（国内站）。国际站是 <a href="https://www.coze.com/" target="_blank" rel="noreferrer">coze.com</a>，账号和渠道不要混用。</li><li>有手机号或抖音账号，用于注册（<a href="https://docs.coze.cn/guides_sign_up" target="_blank" rel="noreferrer">注册登录</a>）。</li><li>不要求会写代码。低代码路径官方原文就是「无论你是否有编程基础」。</li><li>企业员工按套餐走企业/团队入口登录，不要用个人通道硬闯。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>分清「扣子」和「扣子编程」该进哪一个。</li><li>按官方步骤创建一个低代码智能体。</li><li>写一段能约束模型的人设，而不是只填名字。</li><li>知道插件不会自动被调用，必须在人设里引用。</li><li>发布前先在预览区测通。</li></ul><h2 id="第-0-步-进对网站" tabindex="-1">第 0 步：进对网站 <a class="header-anchor" href="#第-0-步-进对网站" aria-label="Permalink to &quot;第 0 步：进对网站&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你以为自己在…</th><th>实际该打开</th><th>不要打开</th></tr></thead><tbody><tr><td>搭智能体 / 工作流</td><td><a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a></td><td>豆包、Trae</td></tr><tr><td>和现成 Agent 一起办公</td><td><a href="https://www.coze.cn/" target="_blank" rel="noreferrer">coze.cn</a></td><td>本教程不走这条</td></tr><tr><td>看文档</td><td><a href="https://docs.coze.cn/" target="_blank" rel="noreferrer">docs.coze.cn</a></td><td>随机搜索到的 2024 年 Bot 博客</td></tr></tbody></table><p>官方把低代码项目定义成扣子编程「较为早期的版本」，但 <strong>新建低代码智能体仍然从扣子编程进入</strong>（<a href="https://docs.coze.cn/about-low-code-project" target="_blank" rel="noreferrer">about-low-code-project</a>、<a href="https://docs.coze.cn/guides_quickstart" target="_blank" rel="noreferrer">guides_quickstart</a>）。</p><p>个人免费版可以先体验。付费档位和积分见 <a href="./coze-cheatsheet.html#套餐与积分">速查表 · 套餐</a>，不要背死价格。</p><h2 id="第-1-步-创建一个低代码智能体" tabindex="-1">第 1 步：创建一个低代码智能体 <a class="header-anchor" href="#第-1-步-创建一个低代码智能体" aria-label="Permalink to &quot;第 1 步：创建一个低代码智能体&quot;">​</a></h2><p>以下步骤逐字对应官方「搭建一个 AI 助手智能体」（夸夸机器人）：</p><ol><li>登录 <strong>扣子编程</strong>。</li><li>顶部选好工作空间，左侧点 <strong>新建项目</strong>。</li><li>在 <strong>低代码模式</strong> 区域点 <strong>智能体开发</strong>。</li><li>填名称和功能介绍。点图标旁的 <strong>生成</strong> 可自动出头像。也可以切到 <strong>AI 创建</strong>，用一句话让平台起草人设。</li><li>点 <strong>确认</strong>。进入编排页： <ul><li>左：<strong>人设与回复逻辑</strong></li><li>中：<strong>技能</strong>（插件、工作流、知识库等）</li><li>右：<strong>预览与调试</strong></li></ul></li></ol><p>来源：<a href="https://docs.coze.cn/guides_quickstart" target="_blank" rel="noreferrer">guides_quickstart</a>。</p><h2 id="第-2-步-写人设-而不是只起名" tabindex="-1">第 2 步：写人设，而不是只起名 <a class="header-anchor" href="#第-2-步-写人设-而不是只起名" aria-label="Permalink to &quot;第 2 步：写人设，而不是只起名&quot;">​</a></h2><p>人设会持续影响所有会话。官方建议写清：角色、语言风格、回答范围。</p><p>夸夸机器人的官方示例（可直接用）：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 角色</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你是一个充满正能量的赞美鼓励机器人，时刻用温暖的话语给予人们赞美和鼓励，让他们充满自信与动力。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 技能</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 技能 1：赞美个人优点</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 当用户提到自己的某个特点或行为时，挖掘其中的优点进行赞美。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 如果用户没有明确提到自己的特点，可以主动询问一些问题，了解用户后进行赞美。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 技能 2：鼓励面对困难</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 当用户提到遇到困难时，给予鼓励和积极的建议。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 如果用户没有提到困难但情绪低落，可以询问是否有不开心的事情，然后给予鼓励。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 技能 3：回答专业问题</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">遇到你无法回答的问题时，调用 Search 搜索答案</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 限制</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 只输出赞美和鼓励的话语，拒绝负面评价。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 所输出的内容必须按照给定的格式进行组织，不能偏离框架要求。</span></span></code></pre></div><p>编排页提供 <strong>自动优化提示词</strong>。优化后仍要自己读一遍，不要默认机器改写就是你的意图。</p><p>模型选择、单 Agent / 多 Agent、Temperature 等见 <a href="https://docs.coze.cn/guides_agent_overview" target="_blank" rel="noreferrer">功能概述</a> 和 <a href="https://docs.coze.cn/guides_llm" target="_blank" rel="noreferrer">设置模型</a>。个人免费版 / 进阶版可用豆包、DeepSeek 等；企业版还可使用方舟上的其他模型。具体名单以控制台为准，不要从旧截图抄模型名。</p><h2 id="第-3-步-只在模型不够用时加技能" tabindex="-1">第 3 步：只在模型不够用时加技能 <a class="header-anchor" href="#第-3-步-只在模型不够用时加技能" aria-label="Permalink to &quot;第 3 步：只在模型不够用时加技能&quot;">​</a></h2><p>官方口径：模型能力已经够用，就只写人设。模型做不到的事（搜新闻、读 PPT、查内部手册）再加技能。</p><p>夸夸机器人加「头条搜索」的官方步骤：</p><ol><li>技能区点 <strong>插件</strong> 旁的 <strong>+</strong>。</li><li>搜索 <strong>头条搜索</strong>，点 <strong>添加</strong>。</li><li>回到人设，输入 <code>{</code>，<strong>引用</strong>这个插件。不引用，智能体可能根本不调它。</li></ol><p>开场白、用户问题建议、背景图、语音是对话体验，不是能力扩展。需要知识库或工作流时去 <a href="./coze-cookbook.html">Cookbook</a>。</p><h2 id="第-4-步-在预览区测-再发布" tabindex="-1">第 4 步：在预览区测，再发布 <a class="header-anchor" href="#第-4-步-在预览区测-再发布" aria-label="Permalink to &quot;第 4 步：在预览区测，再发布&quot;">​</a></h2><p>右侧 <strong>预览与调试</strong> 里先自己聊几轮。</p><p>测这几件事：</p><ul><li>人设有没有被模型忘掉（一上来自称豆包 / DeepSeek 就是没写住人设）。</li><li>加了插件的问题会不会真的走工具。</li><li>你明确禁止的内容会不会漏出来。</li></ul><p>调试台能看到执行过程。线上已经很慢或不回时，也回这里看，不要先猜模型坏了。</p><h2 id="第-5-步-发布" tabindex="-1">第 5 步：发布 <a class="header-anchor" href="#第-5-步-发布" aria-label="Permalink to &quot;第 5 步：发布&quot;">​</a></h2><p>官方步骤：</p><ol><li>编排页右上角点 <strong>发布</strong>。</li><li>填发布记录，勾选渠道。</li><li>再点 <strong>发布</strong>。</li></ol><p>当前官方默认渠道包括：扣子商店 / 作品社区、飞书、微信（客服 / 服务号 / 订阅号）、掘金、抖音/微信小程序、API、Chat SDK。完整表见 <a href="https://docs.coze.cn/guides_publish_overview" target="_blank" rel="noreferrer">发布概览</a> 和 <a href="./coze-cheatsheet.html#发布渠道">速查表</a>。</p><p><strong>不要再选豆包渠道。</strong> 低代码智能体发到豆包的入口已于 <strong>2026-07-01</strong> 下线；已发布的不受影响（<a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">FAQ</a>）。</p><p>发布会先打包，再过扣子审核，再过渠道审核。失败先看页面提示和 <a href="https://docs.coze.cn/guides_content_principles" target="_blank" rel="noreferrer">内容发布规范</a>，不要反复点发布。</p><p>商店和调试区单次对话超时 <strong>10 分钟</strong>，超时表现为「运行中止」。工作流太长先拆短。</p><h2 id="另一条路-全代码智能体" tabindex="-1">另一条路：全代码智能体 <a class="header-anchor" href="#另一条路-全代码智能体" aria-label="Permalink to &quot;另一条路：全代码智能体&quot;">​</a></h2><p>如果你更想「说一句话让平台把智能体写出来」，走 AI 编程，不是上面的低代码画布：</p><ol><li>打开 <a href="https://code.coze.cn/" target="_blank" rel="noreferrer">code.coze.cn</a> 首页。</li><li>点 <strong>智能体</strong> 选项卡。</li><li>写清功能、逻辑、约束，提交。</li><li>等扣子 AI 建项目、跑测试、给出预览。</li></ol><p>费用会走编程任务积分、内置集成、部署后的托管费。步骤详见 <a href="https://docs.coze.cn/guides_vibe_coding_agent" target="_blank" rel="noreferrer">开发智能体</a> 和 <a href="./coze-cookbook.html#用-ai-编程生成全代码智能体">Cookbook</a>。</p><p>扣子（coze.cn）对话里的 AI 编程<strong>不能</strong>替代这一步去开发智能体和工作流。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>智能体自称豆包 / DeepSeek</td><td>人设没覆盖模型默认身份</td><td>在人设里写死名字和职责</td></tr><tr><td>加了插件却从不调用</td><td>人设里没有 <code>{</code> 引用</td><td>按官方要求引用工具</td></tr><tr><td>发布列表里没有豆包</td><td>2026-07-01 下线</td><td>改飞书 / 微信 / API</td></tr><tr><td>调试区「运行中止」</td><td>商店/调试 10 分钟超时</td><td>缩短工作流</td></tr><tr><td>想私有化部署扣子编程</td><td>商业版不支持</td><td>用 <a href="https://github.com/coze-dev/coze-studio" target="_blank" rel="noreferrer">Coze Studio</a></td></tr><tr><td>进了豆包或 Trae</td><td>进错产品</td><td>回到 <a href="./">学习地图</a></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>给智能体加知识库或工作流：<a href="./coze-cookbook.html">Cookbook</a></li><li>查套餐、CLI、渠道：<a href="./coze-cheatsheet.html">速查表</a></li><li>对齐「技能 / 插件 / 工作流」：<a href="./coze-glossary.html">术语表</a></li></ul>`,47)])])}const u=e(i,[["render",o]]);export{f as __pageData,u as default};
